"""Hand-authored scene geometry, reviewed against each source illustration.

Coordinates refer to the uncropped source image; rectangles are x0,y0,x1,y1.
These are artistic regions, not category-wide automatic masks.
"""
import copy

def P(points,feather=.008,erase=False):
    if isinstance(points,str):points=[list(map(float,p.split(','))) for p in points.split()]
    return dict(points=points,feather=feather,erase=erase)
def R(x0,y0,x1,y1,feather=.008):return P([[x0,y0],[x1,y0],[x1,y1],[x0,y1]],feather)
def E(shape):return dict(shape,erase=True)
def W(kind,count=80,box=(0,0,1,1),masks=None,color=None,after=-1):
    colors={'snow':'#DFEFFF','dust':'#EEDBC2','fireflies':'#E2F6B4','rain':'#CBDCED','petals':'#F5C7DC','leaves':'#E9AD5B','embers':'#FFBD79','meteors':'#CDE4FF','bubbles':'#BBDFED'}
    x0,y0,x1,y1=box
    return dict(kind=kind,count=count,region=[x0,y0,x1-x0,y1-y0],masks=masks or [],color=color or colors.get(kind,'#DFEFFF'),afterLayer=after)
def O(surface,mask,opacity=.25,**kw):return dict(surface=surface,r=mask,opacity=opacity,clipToSurface=True,**kw)
def C(hair,breath,face,**kw):return dict(hair=hair,breath=breath,face=face,**kw)
D={}
def S(id,**kw):
    if id in D:raise ValueError('Duplicate direction '+str(id))
    D[id]=kw

